import argparse,json,sys,torch
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT));sys.path.insert(0,str(ROOT/'experiments'))
from tools.tokenizer import Tokenizer
from circuit_io_v1 import save
p=argparse.ArgumentParser();p.add_argument('--output',required=True);a=p.parse_args();torch.set_num_threads(6);torch.set_grad_enabled(False)
host=torch.load(ROOT/'host/ckpt.pt',weights_only=True,mmap=True)['model'];data=torch.load(ROOT/'artifacts/n_host_calib0.pt',weights_only=True,mmap=True);E=host['transformer.wte.weight'].double();P=host['transformer.wpe.weight'][:64].double();tok=Tokenizer();ids=[tok.encode(str(d))[0] for d in range(10)]+[tok.encode(' '+str(d))[0] for d in range(10)]+[tok.encode(' +')[0],tok.encode(' =')[0]];allowed=torch.tensor(ids);mask=torch.ones(len(E),dtype=torch.bool);mask[allowed]=False;u=(torch.arange(64,dtype=torch.float64)-31.5)/32;frequencies=torch.tensor([1.,3.,9.,27.],dtype=torch.float64);angles=2*torch.pi*torch.arange(64,dtype=torch.float64)[:,None]*frequencies[None,:]/64;codes=torch.stack((angles.cos(),angles.sin()),-1).reshape(64,8)/2;D=torch.cat((E[allowed]+P[0],P[1:]-P[0],torch.ones(1,768,dtype=torch.float64)));base=torch.zeros(len(ids),11,dtype=torch.float64);base[:,0]=1;base[:20,1]=torch.arange(10,dtype=torch.float64).repeat(2);base[10:20,2]=1;base[20,2]=2;base[21,2]=3;base[:,3:]=codes[0];shift=torch.zeros(63,11,dtype=torch.float64);shift[:,3:]=codes[1:]-codes[0];targets=torch.cat((base,shift,torch.zeros(1,11,dtype=torch.float64)));_,sing,V=torch.linalg.svd(D,full_matrices=True);rank=int((sing>sing.max()*1e-10).sum());N=V[rank:].T
oldP=host['transformer.h.0.attn.c_proj.weight'].double();oldb=host['transformer.h.0.attn.c_proj.bias'].double();values=data['captures']['0.attn_values'].reshape(-1,768).double();meanv=values.mean(0);covv=values.T@values/len(values)-meanv[:,None]*meanv[None,:];attention=oldP@covv@oldP.T;mean_output=oldP@meanv+oldb;mean_embed=E.mean(0)+P.mean(0);centered=E+P.mean(0);C=centered.T@centered/len(E);attention_metric=attention*(C.trace()/attention.trace());reports=[];best=None
