 metric=C+mass*attention_metric;metric+=torch.eye(768,dtype=torch.float64)*(float(metric.trace()/768)*1e-7);off=N@torch.linalg.solve(N.T@metric@N,N.T@mean_embed);off/=mean_embed@off;chol=torch.linalg.cholesky(metric);white=torch.linalg.solve_triangular(chol,D.T,upper=False).T;U,S,Vh=torch.linalg.svd(white,full_matrices=False);keep=S>S.max()*1e-12;coords=torch.linalg.solve_triangular(chol.T,Vh[keep].T@((U[:,keep].T@targets)/S[keep,None]),upper=True);readouts=torch.cat((off[:,None],coords),1);Q=torch.linalg.qr(readouts,mode='reduced').Q;proj=(oldP-Q@(Q.T@oldP)).float();removed_variance=float(torch.trace(Q.T@attention@Q));removed_mean=Q@(Q.T@mean_output)
